import functools

def semver_sort(versions):
    def parse(v):
        v_no_build = v.split('+', 1)[0]
        if '-' in v_no_build:
            core, pre = v_no_build.split('-', 1)
        else:
            core, pre = v_no_build, None
        major, minor, patch = map(int, core.split('.'))
        return (major, minor, patch, pre)

    def cmp_pre(pre1, pre2):
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # no pre-release sorts after a version with pre-release
        if pre2 is None:
            return -1
        ids1 = pre1.split('.')
        ids2 = pre2.split('.')
        for i in range(min(len(ids1), len(ids2))):
            a, b = ids1[i], ids2[i]
            a_num = a.isdigit()
            b_num = b.isdigit()
            if a_num and b_num:
                ai, bi = int(a), int(b)
                if ai != bi:
                    return -1 if ai < bi else 1
            elif a_num and not b_num:
                return -1
            elif not a_num and b_num:
                return 1
            else:
                if a != b:
                    return -1 if a < b else 1
        if len(ids1) != len(ids2):
            return -1 if len(ids1) < len(ids2) else 1
        return 0

    def cmp(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        for i in range(3):
            if p1[i] != p2[i]:
                return -1 if p1[i] < p2[i] else 1
        return cmp_pre(p1[3], p2[3])

    return sorted(versions, key=functools.cmp_to_key(cmp))

